// Generated by Cypress Author on 2026-10-14
// Stage smoke: proves the harness targets the stage-selected origin and that
// both configured Clerk test users can authenticate. The same spec runs on dev
// and staging with no stage branches; the expected origin is injected by the
// sqldev CLI as E2E_EXPECTED_ORIGIN.

describe("Stage harness smoke → correct origin and both users sign in", () => {
  it("actor 0 lands on the expected origin with a Clerk session", () => {
    cy.signInAsUser(0);
    cy.visit("/");
    cy.assertExpectedOrigin();
    cy.waitForClerkLoaded();
    cy.window().should((win) => {
      expect(win.Clerk.user, "actor 0 Clerk user").to.exist;
    });
  });

  it("actor 1 lands on the expected origin with a Clerk session", () => {
    cy.signInAsUser(1);
    cy.visit("/");
    cy.assertExpectedOrigin();
    cy.waitForClerkLoaded();
    cy.window().should((win) => {
      expect(win.Clerk.user, "actor 1 Clerk user").to.exist;
    });
  });
});
